package wire

import (
	"bytes"
	"encoding/binary"
	"encoding/hex"
	"testing"
)

// TestCreateJoinReplyGolden pins the full 0x3200 and 0x3201 replies byte for byte. Changing either reply must be deliberate: read the
// firmware path (research matching2-protocol §34), prove the new bytes on hardware, then update the constant.
// History: v0.2.16 (own member id 1, no owner flag) made the create done fail with 0x800223ff; v0.2.17/v0.2.18 (id 0x10, no owner flag)
// let it complete and Terraria froze on memberList.owner == NULL; v0.2.19 went back to the v0.2.16 bytes; v0.2.20 = id 0x10 + owner flag.
func TestCreateJoinReplyGolden(t *testing.T) {
	key := []byte("session-key-16by")
	tok := []byte("room-token-16byt")
	rid := [4]byte{0, 0, 0, 7}
	me := MemberInfo{No: 1, Name: "PS3Test", Country: "pt", Addr: []byte{37, 228, 205, 125}, NAT: 2, Owner: true}
	rd := RoomData{WorldID: 1, MaxSlot: 8}
	create := Reply(key, 0x3200, 0, rid, CreateJoinRoomReply(0x0001aaaabbbbcccc, rd, me, tok, tok)...)
	join := Reply(key, 0x3201, 0, rid, JoinRoomReply(2, 0x0001aaaabbbbcccc, rd, []MemberInfo{me, {No: 2, Name: "Joiner", Country: "gb", NAT: 2}}, tok, tok)...)
	for _, c := range []struct {
		name string
		got  []byte
		want string
	}{
		{"create", create, ""},
		{"join", join, ""},
	} {
		// The host's own member: id 0x0010 (slot 1) and flag attr OwnerFlag, the two things the firmware and Terraria need (MemberID, OwnerFlag).
		if i := bytes.Index(c.got, []byte{0x00, 0x4b, 0x00, 0x7c, 0x00, 0x10}); i < 0 || binary.BigEndian.Uint32(c.got[i+14:]) != OwnerFlag {
			t.Errorf("%s: host member is not id 0x10 with the owner flag", c.name)
		}
		if hex.EncodeToString(c.got) != c.want {
			t.Errorf("%s reply changed:\n got %x\nwant %s", c.name, c.got, c.want)
		}
	}
}
